class Solution {
public:
    bool isCousins(TreeNode* root, int x, int y) {
        if (!root) return false;
        queue<pair<TreeNode*, TreeNode*>> q;
        q.push({root, nullptr});
        while (!q.empty()) {
            int sz = q.size();
            TreeNode* xParent = nullptr;
            TreeNode* yParent = nullptr;
            for (int i = 0; i < sz; i++) {
                auto [node, parent] = q.front();
                q.pop();
                if (node->val == x) xParent = parent;
                else if (node->val == y) yParent = parent;
                if (node->left) q.push({node->left, node});
                if (node->right) q.push({node->right, node});
            }
            if (xParent && yParent) return xParent != yParent;
            if (xParent || yParent) return false;
        }
        return false;
    }
};

class Solution {
    public boolean isCousins(TreeNode root, int x, int y) {
        if (root == null) return false;
        Queue<TreeNode[]> q = new LinkedList<>();
        q.offer(new TreeNode[]{root, null});
        while (!q.isEmpty()) {
            int sz = q.size();
            TreeNode xParent = null, yParent = null;
            for (int i = 0; i < sz; i++) {
                TreeNode[] pair = q.poll();
                TreeNode node = pair[0], parent = pair[1];
                if (node.val == x) xParent = parent;
                else if (node.val == y) yParent = parent;
                if (node.left != null) q.offer(new TreeNode[]{node.left, node});
                if (node.right != null) q.offer(new TreeNode[]{node.right, node});
            }
            if (xParent != null && yParent != null) return xParent != yParent;
            if (xParent != null || yParent != null) return false;
        }
        return false;
    }
}

